package org.pocketlore.app;
import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.json.*;
public final class DocumentsRestartInstrumentation extends Instrumentation{
 Bundle args;public void onCreate(Bundle a){args=a;super.onCreate(a);start();}public void onStart(){Bundle result=new Bundle();try{File root=getTargetContext().getFilesDir();String recovery=args.getString("recover");if(recovery!=null){File archive=new File(root,"pack-library/"+recovery+".plpack");KnowledgePack p=KnowledgePack.load(archive);if(!p.id.equals("personal-f23d9ffa8123bab9a6aa173b")||!p.provenance.values().iterator().next().contains("Public test fixture author"))throw new AssertionError("Not task-owned fixture");new PackLibrary(root).remove(recovery);result.putString("stream","Removed exact archived crash fixture\n");finish(-1,result);return;}
 File dir=new File(root,args.getString("directory"));long start=System.nanoTime();PackLibrary.Snapshot s=new PackLibrary(dir).load();if(s.entries.size()!=7||s.engine.research("Amethyst").hits.isEmpty()||s.engine.research("Citrine").hits.isEmpty())throw new AssertionError("Restarted library unavailable");String sentinel=KnowledgePack.hash(Files.readAllBytes(new File(dir,"model.gguf").toPath()));if(!sentinel.equals(KnowledgePack.hash("test sentinel, not a model".getBytes(StandardCharsets.UTF_8))))throw new AssertionError("Sentinel changed");Debug.MemoryInfo m=new Debug.MemoryInfo();Debug.getMemoryInfo(m);JSONObject report=new JSONObject().put("status","PASS").put("pid",android.os.Process.myPid()).put("retained_collections",s.entries.size()).put("archive_bytes",s.archiveBytes).put("reopen_ms",(System.nanoTime()-start)/1e6).put("pss_kib",m.getTotalPss());Files.write(new File(dir,"restart.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));result.putString("stream",report.toString());finish(-1,result);
 }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
